import sys
import itertools
from collections import deque

MOD = 10**9 + 7

def input():
    return sys.stdin.readline()

def bfs_distances(tree, start):
    n = len(tree)
    dist = [0] * n
    visited = [False] * n
    q = deque([start])
    visited[start] = True
    while q:
        u = q.popleft()
        for v in tree[u]:
            if not visited[v]:
                visited[v] = True
                dist[v] = dist[u] + 1
                q.append(v)
